// Hand-added asset wiring, not part of the content/ codegen source. These are
// stylized Quaternius game-asset growth stages, NOT scientifically labeled
// botanical phases (no radicle emergence / cotyledon vs. true-leaf framing) --
// PlantsLab.tsx renders them as an optional "real 3D growth stage" scrub
// layer on top of the existing authored Seed/Flower lesson content, never as
// a replacement for it. Registry ids match modelRegistry.ts (registered by a
// parallel Wave 3 agent) so this file and the registry stay in sync.
export interface GrowthStageModel {
  /** Matches the id registered in modelRegistry.ts / docs/ASSET-LICENSES.md. */
  registryId: string
  label: string
  modelUrl: string
}

